/**
 * Find the most relevant answers based on the query string
 * @param query The search query
 * @param count Number of results to return
 * @returns Array of matching questions
 */
export function findRelevantAnswers(query: string, count: number = 3): FinancialQuestion[] {
  const normalizedQuery = query.toLowerCase();
  
  // Extract keywords from the query (remove common words)
  const stopWords = ['what', 'is', 'are', 'how', 'do', 'does', 'can', 'should', 'will', 'the', 'a', 'an', 'and', 'or', 'but', 'in', 'on', 'at', 'to', 'for', 'of', 'with', 'by', 'from', 'up', 'about', 'into', 'through', 'during', 'before', 'after', 'above', 'below', 'under', 'between', 'among', 'within', 'without', 'along', 'following', 'across', 'behind', 'beyond', 'plus', 'except', 'but', 'up', 'out', 'off', 'over', 'under', 'again', 'further', 'then', 'once'];
  
  const keywords = normalizedQuery
    .split(/\s+/)
    .filter(word => word.length > 2 && !stopWords.includes(word))
    .map(word => word.replace(/[^\w]/g, '')); // Remove punctuation
  
  // Create a simple score for each question based on matches in question, answer, and tags
  const scoredQuestions = financialQADatabase.map(question => {
    let score = 0;
    const questionText = question.question.toLowerCase();
    const answerText = question.answer.toLowerCase();
    const tagText = question.tags.join(' ').toLowerCase();
    
    // Check for keyword matches in different parts
    keywords.forEach(keyword => {
      if (keyword) {
        // Question text matches (highest weight)
        if (questionText.includes(keyword)) {
          score += 10;
        }
        
        // Tag matches (high weight)
        if (tagText.includes(keyword)) {
          score += 8;
        }
        
        // Answer content matches (medium weight)
        if (answerText.includes(keyword)) {
          score += 5;
        }
      }
    });
    
    // Bonus for exact phrase match in question
    if (questionText.includes(normalizedQuery)) {
      score += 15;
    }
    
    // Bonus for exact phrase match in answer
    if (answerText.includes(normalizedQuery)) {
      score += 8;
    }
    
    // Bonus for multiple keyword matches
    const keywordMatches = keywords.filter(keyword => 
      questionText.includes(keyword) || answerText.includes(keyword) || tagText.includes(keyword)
    ).length;
    
    if (keywordMatches > 1) {
      score += keywordMatches * 2;
    }
    
    return { question, score };
  });
  
  // Sort by score (highest first) and take the top 'count' results
  const topResults = scoredQuestions
    .filter(item => item.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, count)
    .map(item => item.question);
  
  // If no results found with keywords, try a broader search
  if (topResults.length === 0) {
    const fallbackResults = financialQADatabase.filter(question => {
      const allText = (question.question + ' ' + question.answer + ' ' + question.tags.join(' ')).toLowerCase();
      return normalizedQuery.split(/\s+/).some(word => 
        word.length > 2 && allText.includes(word.replace(/[^\w]/g, ''))
      );
    }).slice(0, count);
    
    return fallbackResults;
  }
  
  return topResults;
}

/**
 * Get a specific question by ID
 * @param id Question ID to retrieve
 * @returns The question or undefined if not found
 */
export function getQuestionById(id: string): FinancialQuestion | undefined {
  return financialQADatabase.find(q => q.id === id);
}

/**
 * Get related questions by their IDs
 * @param questionIds Array of question IDs to retrieve
 * @returns Array of related questions
 */
export function getRelatedQuestions(questionIds: string[]): FinancialQuestion[] {
  return financialQADatabase.filter(q => questionIds.includes(q.id));
}

/**
 * Get questions by difficulty level
 * @param level Difficulty level (beginner, intermediate, or advanced)
 * @returns Array of questions matching the difficulty level
 */
export function getQuestionsByDifficulty(level: 'beginner' | 'intermediate' | 'advanced'): FinancialQuestion[] {
  return financialQADatabase.filter(q => q.difficulty === level);
}

/**
 * Get questions by tag
 * @param tag Tag to filter by
 * @returns Array of questions that have the specified tag
 */
export function getQuestionsByTag(tag: string): FinancialQuestion[] {
  return financialQADatabase.filter(q => 
    q.tags.some(t => t.toLowerCase() === tag.toLowerCase())
  );
}